#!/usr/bin/env python3
"""
Round 221o (culprits), 17 October 2026. Needs round 220o.

The Rape row's US county count after the last 12 OffenderWatch states.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 221o (17 October)\n\nNeeds round 220o (guards on its heading). No tiles patch. No app.js?v= bump.\nThe owner's rape.html in the maps repo is replaced by the latest build.\n\n- Rape row: 962 US county sheriffs, city police and district attorneys,\n  now from all 34 OffenderWatch state pages the owner saved (the last 12:\n  AR, AZ, CA, CO, CT, FL, GA, ID, KS, MA, MD, MO).\n- Tests: the round 219o block updated.\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round221o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 220o" not in h.read_text(encoding="utf-8"):
        sys.exit("round221o: round 220o must be applied first (round220o_culprits.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round221o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "pipeline/sitemaps/registry.json", check=False)
            sys.exit("round221o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round221o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
